set -u
LOG=$HOME/fish_traces/campaign_split_v6_full.log
until grep -q "\] DONE" "$LOG" 2>/dev/null; do sleep 60; done
exec >> "$LOG" 2>&1
echo "[campaign $(date '+%F %T')] round 2: Isaac sweep again → overhead_isaac_split_v6b"
export FISH_APP_CPUS=${FISH_APP_CPUS:-0,2,4,6,8,10} FISH_OBS_CPUS=${FISH_OBS_CPUS:-12-17} FISH_EVENT_COUNT=0
cd "$(dirname "$0")/.."
DEST_BASE=$HOME/fish_traces/overhead_isaac_split_v6b REPS=3 MODES="base lttng nsys" SMOKE_TIMEOUT=1200 \
  bash scripts/overhead_sweep_v4.sh apriltag bi3d bi3d_freespace dnn_image_encoder dope ess image_proc nvblox segformer stereo_image_proc tensor_rt unet visual_slam
echo "[campaign $(date '+%F %T')] round 2 Isaac rc=$?"
scripts/host_perf_mode.sh status | grep -E "throttle|TCPU"
